"""Prepare/verify an insert-only, list-only release. This script never writes to the DB.

--backup reads public tables using the configured anonymous key. SQL generated by
--prepare is applied separately in a transaction, with preservation and replay guards.
"""
from __future__ import annotations

import argparse
from collections import Counter
from datetime import datetime, timedelta, timezone
import hashlib
import json
from pathlib import Path
import re
from urllib.parse import urlparse

from etl.audit_afterschool_serving import env, fetch
from etl.load_school_afterschool import category, grade_upper, SCHOOL_WIDE

ROOT=Path(__file__).resolve().parents[1]
RESEARCH=ROOT/'docs/research/seoul-gap37-20261019'
WORK=ROOT/'etl/runtime/seoul-gap37-publish-20261019'
EXPORT=ROOT/'etl/runtime/llm_extraction/outputs_afterschool/seoul_gap37_reviewed'
DAY='2026-10-19'
SOURCE='학교알리미 15-라 방과후·돌봄 운영계획 2026년 공시 (목록 검토·시각 미반영)'
BASELINE={'summary':{'rows':536,'fingerprint':'69e478cb2a9749fa02b7e0476ee69ae1'},
          'programs':{'rows':19831,'fingerprint':'e187d1afd27afa8d92234d94ee5ee09e'}}
# Explicit table-scope review. Others remain in research; no blanket release of 37 schools.
ALLOW={
    'B000001856':None, 'B000001880':None, 'B000001907':None, 'B000001908':None,
    'B000001909':None, 'B000001926':None, 'B000001927':None, 'B000001928':None,
    'B000001929':None, 'B000001993':[(341,385)], 'B000002039':[(62,107)],
    'B000002078':None, 'B000002079':None, 'B000002080':None, 'B000002081':None,
    'B000002095':None, 'B000002107':None, 'B000002251':[(61,89),(94,98),(783,783)],
    'B000002274':None, 'B000002324':None, 'B000002386':None, 'B000002388':None,
    'B000002413':None, 'B000002414':None, 'B000002416':None, 'B000002431':None,
}


def read(path):return json.loads(path.read_text(encoding='utf-8'))
def save(path,value):
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def digest(data):return hashlib.sha256(data).hexdigest()


def public_snapshot():
    url,key=env()
    if urlparse(url).hostname!='vsgeksumgvcrkzjwvlgs.supabase.co':
        raise ValueError('Configured database is not the authorized project')
    return {table:fetch(url,key,table,'*','&order='+order) for table,order in [
        ('school_afterschool_summary','school_id'),('school_afterschool_programs','school_id,seq')]}


def select_release(data):
    summaries=[];programs=[];exports=[];decisions=[];provenance=[]
    for school in data['schools']:
        sid=school['school_id'];seen=set();picked=[];picked_lines=[];reasons=Counter()
        sources={s['sha256']:s for s in school['sources']}
        input_data=(ROOT/school['input_path']).read_bytes()
        if digest(input_data)!=school['input_sha256']:raise ValueError('Research input changed')
        source_lines={int(m[1]):m[2] for line in input_data.decode('utf-8').splitlines()
                      if (m:=re.match(r'L(\d+):\s?(.*)',line))}
        for row in school['rows']:
            line=row['evidence'][0]['input_line']
            if sid not in ALLOW:reasons['school_scope_pending']+=1;continue
            if ALLOW[sid] and not any(a<=line<=b for a,b in ALLOW[sid]):
                reasons['programme_scope_pending']+=1;continue
            src=sources[row['evidence'][0]['sha256']]
            year_ok=src['filename_year']==2026
            if sid=='B000001909':year_ok='2026학년도 1학기 방과후학교' in source_lines.get(46,'')
            if not year_ok:reasons['document_year_pending']+=1;continue
            if row['source_year_conflict']:reasons['row_year_conflict']+=1;continue
            if row['grade1']=='false':reasons['not_grade1']+=1;continue
            if row['kind']=='맞춤형' and (sid!='B000001907' or row['grade1']!='true' or not row['grades_raw']):
                reasons['custom_scope_pending']+=1;continue
            name=row['name']
            if re.search(r'아침|오전|굿모닝|\[토\]|^토요|^\(토\)',name):
                reasons['outside_weekday_afternoon_scope']+=1;continue
            if len(name)>70 or re.match(r'^[1-6][\d,~ -]*(?:반|=)',name):
                reasons['course_name_pending']+=1;continue
            grades=row['grades_raw']
            if not grades and any(g['scope']=='school_wide_target' for g in school['grade_scope_guidance']):
                grades=SCHOOL_WIDE # original grade1 stays unknown
            # Keep source spelling, but collapse whitespace for detecting repeated list entries.
            identity=(row['kind'],re.sub(r'\s+','',name),re.sub(r'\s+','',grades or ''),row['grade1'])
            if identity in seen:reasons['same_list_entry_collapsed']+=1;continue
            seen.add(identity)
            picked.append({'kind':row['kind'],'name':name,'variant':None,'section':None,
                           'category':category(name),'grade1':row['grade1'],'grades_raw':grades,
                           'grade_upper':None if grades==SCHOOL_WIDE else grade_upper(grades),
                           'weekdays':None,'start_time':None,'end_time':None,'term':None})
            picked_lines.append(line)
            provenance.append({'school_id':sid,'research_row_id':row['research_row_id'],
                               'input_sha256':school['input_sha256'],'name':name,'evidence':row['evidence'],
                               'grade_evidence':row.get('grade_evidence',[]),'source_url':src['source_url'],
                               'source_text_sha256':src['text_sha256']})
        decisions.append({'school_id':sid,'school_name':school['school_name'],'research_rows':len(school['rows']),
                          'accepted_rows':len(picked),'excluded_counts':dict(reasons)})
        if not picked:continue
        options={}
        for row in picked:
            key=(row['kind'],row['name'])
            options[key]=options.get(key,False) or row['grade1']=='true'
        summary={'school_id':sid,'source_year':2026,'tier':'C',
                 'grade1_options':sum(options.values()),'custom_options':sum(k[0]=='맞춤형' for k in options),
                 'unknown_grade_options':sum(not v for v in options.values()),
                 **{f'latest_end_{d}':None for d in ('mon','tue','wed','thu','fri')},
                 'timeline_basis':None,'term_label':None,'source':SOURCE,'review_state':'auto','snapshot_date':DAY}
        summaries.append(summary)
        for n,row in enumerate(picked,1):programs.append({'school_id':sid,'seq':n,**row})
        exports.append({'school_id':sid,'rows':[[r['kind'],r['name'],None,None,r['grades_raw'],None,None,None,
                                              r['grade1'],None,line] for r,line in zip(picked,picked_lines)],
                        'input_path':school['input_path'],'input_sha256':school['input_sha256'],
                        'spec_version':'gap37-reviewed-list-only-v1',
                        'term':None,'note':'추가 검수 목록만. 요일·시각은 공개 반영에서 제외. publication_provenance.json 참조.'})
    payload={'school_afterschool_summary':summaries,'school_afterschool_programs':programs}
    validate(payload)
    return payload,exports,decisions,provenance


def validate(payload):
    ss=payload['school_afterschool_summary'];pp=payload['school_afterschool_programs']
    ids={s['school_id'] for s in ss}
    if not ids or len(ids)!=len(ss):raise ValueError('Empty or duplicate school payload')
    for s in ss:
        if s['tier']!='C' or s['timeline_basis'] is not None or any(s[f'latest_end_{d}'] for d in ('mon','tue','wed','thu','fri')):
            raise ValueError('List-only summary gate violated')
    for p in pp:
        if p['school_id'] not in ids or p['grade1'] not in ('true','unknown'):
            raise ValueError('Programme scope/grade gate violated')
        if any(p[k] is not None for k in ('weekdays','start_time','end_time')):
            raise ValueError('List-only programme gate violated')
        if p['kind']=='맞춤형' and (p['grade1']!='true' or not p['grades_raw']):
            raise ValueError('No policy-default grade for new custom programmes')


def sql_literal(value):
    if value is None:return 'NULL'
    if isinstance(value,int):return str(value)
    return "'"+str(value).replace("'","''")+"'"


def build_sql(payload,batch_ids,all_ids,commit=False):
    validate(payload)
    ss=[s for s in payload['school_afterschool_summary'] if s['school_id'] in batch_ids]
    pp=[p for p in payload['school_afterschool_programs'] if p['school_id'] in batch_ids]
    if len(ss)!=len(batch_ids) or not pp:raise ValueError('Invalid SQL batch scope')
    ids=','.join(sql_literal(s) for s in sorted(all_ids))
    js=json.dumps(ss,ensure_ascii=False,separators=(',',':'))
    jp=json.dumps(pp,ensure_ascii=False,separators=(',',':'))
    tag='$gap37_'+digest((js+jp).encode())[:20]+'$'
    if tag in js+jp:raise ValueError('SQL delimiter collision')
    sset='jsonb_populate_recordset(NULL::public.school_afterschool_summary,inc_s)'
    pset='jsonb_populate_recordset(NULL::public.school_afterschool_programs,inc_p)'
    sc=','.join(ss[0]);pc=','.join(pp[0])
    ending='COMMIT;' if commit else 'ROLLBACK;'
    return f"""BEGIN;
SET LOCAL standard_conforming_strings=on;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
LOCK TABLE public.school_afterschool_summary, public.school_afterschool_programs IN SHARE ROW EXCLUSIVE MODE;
DO {tag}
DECLARE inc_s jsonb := {sql_literal(js)}::jsonb; inc_p jsonb := {sql_literal(jp)}::jsonb;
        h text; n bigint; overlap_count bigint;
BEGIN
 SELECT count(*),md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY school_id)::text,'[]')) INTO n,h
 FROM public.school_afterschool_summary t WHERE school_id NOT IN ({ids});
 IF n<>536 OR h<>'{BASELINE['summary']['fingerprint']}' THEN RAISE EXCEPTION 'Existing summary changed; abort'; END IF;
 SELECT count(*),md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY school_id,seq)::text,'[]')) INTO n,h
 FROM public.school_afterschool_programs t WHERE school_id NOT IN ({ids});
 IF n<>19831 OR h<>'{BASELINE['programs']['fingerprint']}' THEN RAISE EXCEPTION 'Existing programmes changed; abort'; END IF;
 SELECT count(*) INTO overlap_count FROM public.school_afterschool_summary t JOIN {sset} i USING(school_id);
 IF overlap_count>0 THEN
   IF overlap_count<>jsonb_array_length(inc_s) OR EXISTS (
     SELECT 1 FROM {sset} i JOIN public.school_afterschool_summary t USING(school_id)
     WHERE to_jsonb(i)-'updated_at' IS DISTINCT FROM to_jsonb(t)-'updated_at'
   ) OR EXISTS (
     (SELECT to_jsonb(p) FROM public.school_afterschool_programs p JOIN {sset} s USING(school_id)
      EXCEPT SELECT to_jsonb(p) FROM {pset} p)
     UNION ALL
     (SELECT to_jsonb(p) FROM {pset} p EXCEPT SELECT to_jsonb(p) FROM public.school_afterschool_programs p JOIN {sset} s USING(school_id))
   ) THEN RAISE EXCEPTION 'Partial/different target rows exist; abort'; END IF;
 ELSE
   IF EXISTS(SELECT 1 FROM public.school_afterschool_programs p JOIN {sset} s USING(school_id))
     THEN RAISE EXCEPTION 'Unexpected target programmes exist'; END IF;
   INSERT INTO public.school_afterschool_summary ({sc}) SELECT {sc} FROM {sset};
   INSERT INTO public.school_afterschool_programs ({pc}) SELECT {pc} FROM {pset};
 END IF;
 IF (SELECT count(*) FROM public.school_afterschool_programs p JOIN {sset} s USING(school_id))<>{len(pp)}
   THEN RAISE EXCEPTION 'Programme count mismatch'; END IF;
END {tag};
SELECT {len(ss)} AS batch_schools,{len(pp)} AS batch_programs,
       (SELECT count(*) FROM public.school_afterschool_summary) AS total_schools,
       (SELECT count(*) FROM public.school_afterschool_programs) AS total_programs;
{ending}
"""


def build_rollback_sql(payload,batch_ids,all_ids):
    """Manual inverse: exact-match guards must pass before deleting release rows."""
    sql=build_sql(payload,batch_ids,all_ids)
    sql=re.sub(r'   INSERT INTO public.school_afterschool_summary .*?;\n   INSERT INTO public.school_afterschool_programs .*?;',
               "   RAISE EXCEPTION 'Rollback target missing; abort';",sql)
    ids=','.join(sql_literal(s) for s in sorted(batch_ids))
    pos=sql.index('\nSELECT '+str(len(batch_ids))+' AS batch_schools')
    return sql[:pos]+f"""
DELETE FROM public.school_afterschool_programs WHERE school_id IN ({ids});
DELETE FROM public.school_afterschool_summary WHERE school_id IN ({ids});
COMMIT;
"""


def prepare():
    payload,exports,decisions,provenance=select_release(read(RESEARCH/'combined_research.json'))
    backup=read(WORK/'live_before.json')
    ids={s['school_id'] for s in payload['school_afterschool_summary']}
    if ids & {s['school_id'] for s in backup['school_afterschool_summary']}:raise ValueError('Release targets already present in backup')
    save(WORK/'payload.json',payload);save(RESEARCH/'publication_decisions.json',decisions)
    save(RESEARCH/'publication_provenance.json',provenance)
    export_path=EXPORT/'batch_20261019_list_only.json'
    if export_path.exists() and read(export_path)!=exports:raise ValueError('Existing approved export differs')
    save(export_path,exports)
    ordered=sorted(ids);batches=[ordered[:2]]+[ordered[i:i+4] for i in range(2,len(ordered),4)]
    for index,batch in enumerate(batches,1):
        for mode in ('dry','apply'):
            (WORK/f'{index:02}_{mode}.sql').write_text(build_sql(payload,batch,ids,mode=='apply'),encoding='utf-8')
        (WORK/f'{index:02}_rollback_manual.sql').write_text(build_rollback_sql(payload,batch,ids),encoding='utf-8')
    (WORK/'all_rollback_manual.sql').write_text(build_rollback_sql(payload,ordered,ids),encoding='utf-8')
    summary={'snapshot_date':DAY,'new_schools':len(ids),'new_rows':len(payload['school_afterschool_programs']),
             'by_kind':dict(Counter(p['kind'] for p in payload['school_afterschool_programs'])),
             'all_list_only':True,'batches':batches,'payload_sha256':digest((WORK/'payload.json').read_bytes()),
             'backup_sha256':digest((WORK/'live_before.json').read_bytes())}
    save(RESEARCH/'publication_plan.json',summary)
    print(json.dumps(summary,ensure_ascii=True,indent=2))


def verify():
    payload=read(WORK/'payload.json');before=read(WORK/'live_before.json');after=public_snapshot()
    ids={s['school_id'] for s in payload['school_afterschool_summary']};errors=[]
    for table,keys in [('school_afterschool_summary',('school_id',)),('school_afterschool_programs',('school_id','seq'))]:
        old={tuple(r[k] for k in keys):r for r in before[table]}
        got={tuple(r[k] for k in keys):r for r in after[table]}
        if any(got.get(k)!=v for k,v in old.items()):errors.append(table+':existing_changed')
        expected=payload[table]
        new=[r for r in after[table] if r['school_id'] in ids]
        if len(new)!=len(expected):errors.append(table+':new_count')
        for row in expected:
            actual=got.get(tuple(row[k] for k in keys))
            if actual is None or any(actual.get(k)!=v for k,v in row.items()):errors.append(table+':new_data');break
    result={'checked_on':DAY,'existing_schools_preserved':len(before['school_afterschool_summary']),
            'existing_rows_preserved':len(before['school_afterschool_programs']),
            'live_schools':len(after['school_afterschool_summary']),'live_rows':len(after['school_afterschool_programs']),
            'custom_schools':len({r['school_id'] for r in after['school_afterschool_programs'] if r['kind']=='맞춤형'}),
            'errors':errors,'public_anonymous_read':True}
    save(RESEARCH/'publication_verification.json',result);save(WORK/'live_after.json',after)
    print(json.dumps(result,ensure_ascii=True,indent=2))
    if errors:raise SystemExit(1)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode',choices=['backup','prepare','verify']);args=parser.parse_args()
    if args.mode=='backup':
        path=WORK/'live_before.json'
        if path.exists():raise SystemExit('Backup exists; never overwrite it')
        backup=public_snapshot()
        if len(backup['school_afterschool_summary'])!=536 or len(backup['school_afterschool_programs'])!=19831:
            raise ValueError('Live baseline changed before backup')
        save(path,backup)
        print(json.dumps({'backup':str(path),'sha256':digest(path.read_bytes()),'counts':{k:len(v) for k,v in backup.items()}}))
    elif args.mode=='prepare':prepare()
    else:verify()


if __name__=='__main__':main()
